CREATE TABLE `sys_operation_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `username` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `method` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `path` varchar(128) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `request_params` mediumtext COLLATE utf8mb4_general_ci,
  `response_params` mediumtext COLLATE utf8mb4_general_ci,
  `ip` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `user_agent` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `code` int NOT NULL DEFAULT '0',
  `cost_ms` bigint NOT NULL DEFAULT '0',
  `client` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_sys_operation_log_user_id` (`user_id`),
  KEY `idx_sys_operation_log_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户操作日志表';

