CREATE TABLE `sys_payment_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `channel` tinyint NOT NULL COMMENT '1微信支付 2支付宝',
  `app_id` varchar(128) COLLATE utf8mb4_general_ci NOT NULL,
  `merchant_id` varchar(128) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `private_key` text COLLATE utf8mb4_general_ci,
  `public_key` text COLLATE utf8mb4_general_ci,
  `api_v3_key` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `cert_serial_no` varchar(128) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `notify_url` varchar(500) COLLATE utf8mb4_general_ci NOT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `sort` int NOT NULL DEFAULT '0',
  `remark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_sys_payment_config_deleted_at` (`deleted_at`),
  KEY `idx_sys_payment_config_channel` (`channel`),
  KEY `idx_sys_payment_config_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='支付渠道配置';

CREATE TABLE `sys_platform_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间',
  `type` tinyint unsigned NOT NULL COMMENT '平台类型，1管理端，2用户端',
  `logo` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理端Logo相对路径',
  `system_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理端系统名称',
  `default_nickname` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户端默认昵称',
  `default_avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户端默认头像相对路径',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_platform_type` (`type`),
  KEY `idx_sys_platform_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='平台基础配置表';

