CREATE TABLE `sys_sms_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `provider` tinyint NOT NULL COMMENT '1阿里云 2腾讯云',
  `access_key_id` varchar(128) COLLATE utf8mb4_general_ci NOT NULL,
  `access_key_secret` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `endpoint` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `status` tinyint NOT NULL DEFAULT '1',
  `remark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_sys_sms_config_deleted_at` (`deleted_at`),
  KEY `idx_sys_sms_config_provider` (`provider`),
  KEY `idx_sys_sms_config_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='短信开发配置';

CREATE TABLE `sys_sms_send_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `config_id` bigint unsigned NOT NULL,
  `signature_id` bigint unsigned NOT NULL DEFAULT '0',
  `template_id` bigint unsigned NOT NULL DEFAULT '0',
  `mobile` varchar(32) COLLATE utf8mb4_general_ci NOT NULL,
  `content` varchar(1000) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `status` tinyint NOT NULL COMMENT '1待发送 2成功 3失败',
  `provider_message_id` varchar(128) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `error_message` varchar(500) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `sent_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sys_sms_send_log_config_id` (`config_id`),
  KEY `idx_sys_sms_send_log_mobile` (`mobile`),
  KEY `idx_sys_sms_send_log_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='短信发送记录';

CREATE TABLE `sys_sms_signature` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `config_id` bigint unsigned NOT NULL,
  `name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `sign_code` varchar(128) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `status` tinyint NOT NULL DEFAULT '1',
  `remark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_sys_sms_signature_deleted_at` (`deleted_at`),
  KEY `idx_sys_sms_signature_config_id` (`config_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='短信签名';

CREATE TABLE `sys_sms_template` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `config_id` bigint unsigned NOT NULL,
  `name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `template_code` varchar(128) COLLATE utf8mb4_general_ci NOT NULL,
  `type` tinyint NOT NULL COMMENT '1验证码 2通知 3营销',
  `content` varchar(500) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `status` tinyint NOT NULL DEFAULT '1',
  `remark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_sys_sms_template_deleted_at` (`deleted_at`),
  KEY `idx_sys_sms_template_config_id` (`config_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='短信模板';

CREATE TABLE `sys_storage_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '渠道名称',
  `channel` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '渠道类型: local/alioss/cos/qiniu/minio',
  `params` text COLLATE utf8mb4_general_ci COMMENT '渠道参数JSON',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '1默认渠道',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 2禁用',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `remark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `default_slot` tinyint GENERATED ALWAYS AS ((case when ((`deleted_at` is null) and (`is_default` = 1)) then 1 else NULL end)) STORED COMMENT '保证全局至多一个有效默认渠道',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_storage_default_slot` (`default_slot`),
  KEY `idx_sys_storage_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='文件存储渠道配置表';

