CREATE TABLE `sys_upload_file` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `file_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '原始文件名',
  `hash_name` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台hash名(md5+扩展名)',
  `size` bigint NOT NULL DEFAULT '0' COMMENT '文件大小(字节)',
  `mime_type` varchar(128) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件类型(MIME)',
  `ext` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件扩展名',
  `client` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '来源: admin/api',
  `relative_path` varchar(512) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件相对路径(云端为对象Key)',
  `absolute_path` varchar(1024) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件绝对路径(云端为完整访问URL)',
  `uploader_id` bigint unsigned DEFAULT NULL COMMENT '上传人ID(可空)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_upload_file_hash_name` (`hash_name`),
  KEY `idx_sys_upload_file_uploader_id` (`uploader_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='上传文件记录表';

