(2, '2026-09-23 16:51:28', '2026-09-23 21:52:35.466', NULL, 'zhangsan', '$2a$10$xBQeertsN46doGwzCyVFx.sJ51JOtSvntXzdv5PMmucSXWZEXfxoe', '张三', 'uploads/2026/09/23/7ebe1037451fcc1546d7dd2662dde803.png', '13800000002', 'zhangsan@example.com', 3, 1, 0);

CREATE TABLE `sys_user_login` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `login_id` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '登录唯一标识(uuid)',
  `user_id` bigint unsigned NOT NULL COMMENT '用户ID',
  `username` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '登录名',
  `client` varchar(16) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT 'admin/api',
  `login_ip` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '登录IP',
  `user_agent` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT 'UA',
  `login_at` datetime(3) DEFAULT NULL COMMENT '登录时间',
  `logout_at` datetime(3) DEFAULT NULL COMMENT '退出时间',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1在线 2已退出 3被踢下线',
  PRIMARY KEY (`id`),
  UNIQUE KEY `login_id` (`login_id`),
  KEY `idx_sys_user_login_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='登录流水表';

