CREATE TABLE `sys_wechat_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `type` tinyint NOT NULL COMMENT '1公众号 2开放平台 3小程序',
  `app_id` varchar(128) COLLATE utf8mb4_general_ci NOT NULL,
  `app_secret` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `token` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `aes_key` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `status` tinyint NOT NULL DEFAULT '1',
  `remark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_wechat_config_app_id` (`app_id`),
  KEY `idx_sys_wechat_config_deleted_at` (`deleted_at`),
  KEY `idx_sys_wechat_config_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='微信应用配置';

SET FOREIGN_KEY_CHECKS = 1;
